CREATE TABLE `roles` (`code` VARCHAR(64) CHARACTER SET ascii NOT NULL,`name` VARCHAR(80) NOT NULL,`category` ENUM('organization','platform') NOT NULL,`description` VARCHAR(255) NOT NULL,`status` ENUM('active','disabled') NOT NULL DEFAULT 'active',`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`code`),KEY `idx_roles_category_status`(`category`,`status`,`code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
